d=pd.read_csv(A/'metadata-only.csv');d=d.sort_values('screen').drop_duplicates(['pair','SIDM'])
def bucket(s):return int(hashlib.sha256(('20261024-drug-growth:'+s).encode()).hexdigest()[:12],16)%10
d['cell_bucket']=d.SIDM.map(bucket);d['pair_bucket']=d.pair.map(bucket)
testpairs=set(d.loc[d.screen=='gdsc-010','pair']);isdev=~d.pair.isin(testpairs)
train=isdev & (d.pair_bucket<8) & (d.cell_bucket<6)
val=isdev & (d.pair_bucket>=8) & d.cell_bucket.between(6,7)
test=(d.screen=='gdsc-010') & (d.cell_bucket>=8)
samples=d.loc[train|val|test,['pair','SIDM','screen','TISSUE','CANCER_TYPE']].copy();samples['split']='train';samples.loc[val[val].index,'split']='validation';samples.loc[test[test].index,'split']='test';samples['sample_id']=samples.pair+'::'+samples.SIDM;samples['cell_line_id']=samples.SIDM;samples['drug_pair_id']=samples.pair
samples.to_csv(P/'samples-frozen.csv',index=False)
ar=audit(P/'samples-frozen.csv',independent_unit='cell_line',group_columns=['cell_line_id','drug_pair_id'],strategy='group',project_root=P)
assert ar['valid'],ar
(P/'split-audit-frozen.json').write_text(json.dumps(ar,indent=2)+'\n')
